mapper.select:
SELECT t.renewal_id, t.tenant_id, t.instance_id, t.renewal_no, t.customer_id, t.customer_name, t.contract_id, t.contract_no, t.renewal_name, t.renewal_amount, t.expected_sign_date, t.current_expire_date, t.next_expire_date, t.owner_id, t.owner_name, t.summary, t.remark, t.status, t.del_flag, t.create_by, t.create_time, t.update_by, t.update_time, c.dept_id AS scope_dept_id, c.owner_id AS scope_owner_id FROM oa_crm_renewal t INNER JOIN oa_crm_customer c ON c.customer_id = t.customer_id AND c.del_flag = '0' WHERE t.del_flag = '0'
AND t.customer_id = #{query.customerId}
AND t.contract_id = #{query.contractId}
AND t.renewal_name LIKE CONCAT('%', #{query.renewalName}, '%')
AND t.status = #{query.status}
ORDER BY t.update_time DESC
